function today(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:s?.settings?.timeZone||'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-')}
function addDays(d,n){const v=new Date(d+'T12:00:00Z');v.setUTCDate(v.getUTCDate()+n);return v.toISOString().slice(0,10)}
function weekday(d){return new Date(d+'T12:00:00Z').getUTCDay()}
function dateLabel(d,opts={month:'short',day:'numeric'}){return new Intl.DateTimeFormat('en-US',{...opts,timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'))}
function schedule(h,d){const change=[...h.scheduleChanges].filter(c=>c.from<=d).sort((a,b)=>a.from.localeCompare(b.from)).at(-1);return change?.days||h.scheduleChanges[0].days}
function habitDue(h,d){return !h.archived&&h.createdOn<=d&&schedule(h,d).includes(weekday(d))}
function hlog(h,d){return s.habitLogs.find(l=>l.habitId===h.id&&l.date===d)}
function habitDone(h,d){const l=hlog(h,d);return !!l&&l.value>=l.target}
function habitStreak(h,d=today()){let count=0,v=d;if(!habitDone(h,v))v=addDays(v,-1);for(let n=0;n<3660&&v>=h.createdOn;n++,v=addDays(v,-1)){if(!schedule(h,v).includes(weekday(v)))continue;if(habitDone(h,v))count++;else break}return count}
function taskDue(t,d=today()){return !t.archived&&(t.repeat==='none'||(t.dueDate<=d&&(t.repeat==='daily'||weekday(t.dueDate)===weekday(d))))}
function taskKey(t,d=today()){return t.id+'|'+(t.repeat==='none'?'once':d)}
function tlog(t,d=today()){return s.taskLogs.find(l=>l.key===taskKey(t,d))}
function taskDone(t,d=today()){return !!tlog(t,d)?.done}
function activeDays(){return new Set([...s.habitLogs.filter(l=>l.value>=l.target).map(l=>l.date),...s.taskLogs.filter(l=>l.done).map(l=>l.doneOn),...s.focusSessions.map(f=>f.date)])}
function overallStreak(){let ds=activeDays(),v=today(),n=0;if(!ds.has(v))v=addDays(v,-1);while(ds.has(v)&&n<3660){n++;v=addDays(v,-1)}return n}
function questInfo(d){const h=s.habitLogs.filter(l=>l.date===d&&l.value>=l.target).length,t=s.taskLogs.filter(l=>l.done&&l.doneOn===d).length,f=s.focusSessions.filter(f=>f.date===d).length;return [{id:'habits',name:'Show up for yourself',description:`Complete 3 habits · ${Math.min(h,3)}/3`,done:h>=3,xp:20,icon:'habits'},{id:'task',name:'Move one thing forward',description:`Complete a task · ${Math.min(t,1)}/1`,done:t>=1,xp:15,icon:'tasks'},{id:'focus',name:'Make a little space',description:`Finish a focus session · ${Math.min(f,1)}/1`,done:f>=1,xp:15,icon:'focus'}]}
function game(){const hc=s.habitLogs.filter(l=>l.value>=l.target),tc=s.taskLogs.filter(l=>l.done),sessions=[...s.focusSessions].sort((a,b)=>a.completedAt.localeCompare(b.completedAt));let xp=hc.reduce((n,l)=>n+l.xp,0)+tc.reduce((n,l)=>n+l.xp,0),focusCounts={};for(const f of sessions){focusCounts[f.date]=(focusCounts[f.date]||0)+1;if(focusCounts[f.date]<=4)xp+=20}for(const d of activeDays())xp+=questInfo(d).filter(q=>q.done).reduce((n,q)=>n+q.xp,0);let level=1;while(50*level*(level+1)<=xp)level++;const base=50*(level-1)*level,next=50*level*(level+1),spent=s.redemptions.reduce((n,r)=>n+r.cost,0);return {xp,level,base,next,within:xp-base,needed:next-base,coins:Math.floor(xp/10)-spent,hc:hc.length,tc:tc.length,focus:sessions.length,minutes:sessions.reduce((n,f)=>n+f.minutes,0),title:level>=10?'Architect':level>=5?'Pathfinder':level>=2?'Builder':'New explorer'}}
// CORE END
function seed(){const d=today(),all=[0,1,2,3,4,5,6];return {settings:{name:'',timeZone:'America/Sao_Paulo',theme:'system',dailyGoal:100},habits:[{id:id(),title:'Read for 10 minutes',notes:'A chapter, a few pages, or a little curiosity.',area:'mind',effort:'normal',target:1,unit:'session',createdOn:d,scheduleChanges:[{from:d,days:all}],archived:false},{id:id(),title:'Move your body',notes:'A walk, a run, or a home workout. Keep it kind.',area:'body',effort:'normal',target:1,unit:'session',createdOn:d,scheduleChanges:[{from:d,days:all}],archived:false},{id:id(),title:'Practice a little Russian',notes:'Ten focused minutes is enough to begin.',area:'mind',effort:'easy',target:1,unit:'session',createdOn:d,scheduleChanges:[{from:d,days:all}],archived:false}],tasks:[],habitLogs:[],taskLogs:[],focusSessions:[],rewards:[{id:id(),title:'An episode of a favorite show',cost:20,archived:false},{id:id(),title:'A slow, screen-free reading break',cost:10,archived:false}],redemptions:[]}}
function valid(v){const str=(x,n)=>typeof x==='string'&&x.length<=n,dt=x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(Date.parse(x+'T12:00:00Z'))&&new Date(x+'T12:00:00Z').toISOString().slice(0,10)===x,ids=a=>new Set(a.map(x=>x.id||x.key)).size===a.length,int=(n,min,max)=>Number.isInteger(n)&&n>=min&&n<=max,area=a=>Object.hasOwn(areas,a),effort=a=>Object.hasOwn(XP,a);if(!v||!v.settings||!int(v.settings.dailyGoal,10,1000)||!str(v.settings.name,40)||!['system','light','dark'].includes(v.settings.theme))return false;try{new Intl.DateTimeFormat('en',{timeZone:v.settings.timeZone}).format()}catch{return false}for(const [k,max]of Object.entries({habits:100,tasks:800,habitLogs:6000,taskLogs:4000,focusSessions:2000,rewards:100,redemptions:1000}))if(!Array.isArray(v[k])||v[k].length>max||!ids(v[k]))return false;return v.habits.every(h=>str(h.id,80)&&str(h.title,140)&&h.title.trim()&&str(h.notes,1200)&&area(h.area)&&effort(h.effort)&&int(h.target,1,1000)&&str(h.unit,18)&&dt(h.createdOn)&&typeof h.archived==='boolean'&&Array.isArray(h.scheduleChanges)&&h.scheduleChanges.length>0&&h.scheduleChanges.length<=100&&h.scheduleChanges.every(c=>dt(c.from)&&Array.isArray(c.days)&&c.days.length>0&&c.days.every(d=>int(d,0,6))))&&v.tasks.every(t=>str(t.id,80)&&str(t.title,140)&&t.title.trim()&&str(t.notes,1200)&&area(t.area)&&effort(t.effort)&&['high','normal','low'].includes(t.priority)&&['none','daily','weekly'].includes(t.repeat)&&['todo','doing'].includes(t.status)&&(t.dueDate===''||dt(t.dueDate))&&(t.repeat==='none'||!!t.dueDate)&&dt(t.createdOn)&&typeof t.archived==='boolean'&&Array.isArray(t.subtasks)&&t.subtasks.length<=8&&t.subtasks.every(q=>str(q.id,80)&&str(q.title,100)))&&v.habitLogs.every(l=>str(l.id,170)&&str(l.habitId,80)&&dt(l.date)&&l.id===l.habitId+'|'+l.date&&int(l.value,0,1000)&&int(l.target,1,1000)&&[10,20,40].includes(l.xp)&&area(l.area))&&v.taskLogs.every(l=>str(l.key,170)&&str(l.taskId,80)&&dt(l.date)&&(l.key===l.taskId+'|once'||l.key===l.taskId+'|'+l.date)&&typeof l.done==='boolean'&&(!l.done||dt(l.doneOn))&&[10,20,40].includes(l.xp)&&area(l.area)&&Array.isArray(l.steps)&&l.steps.every(q=>str(q,80)))&&v.focusSessions.every(f=>str(f.id,80)&&dt(f.date)&&int(f.minutes,5,90)&&str(f.completedAt,40)&&str(f.taskTitle||'',140))&&v.rewards.every(r=>str(r.id,80)&&str(r.title,100)&&r.title.trim()&&int(r.cost,1,100000)&&typeof r.archived==='boolean')&&v.redemptions.every(r=>str(r.id,80)&&str(r.title,100)&&int(r.cost,1,100000)&&dt(r.date))}
const stateKeys=['settings','habits','tasks','habitLogs','taskLogs','focusSessions','rewards','redemptions'];
function pure(data){return Object.fromEntries(stateKeys.map(k=>[k,clone(data[k])]))}
function applyTheme(){const val=s?.settings.theme||'system';document.documentElement.dataset.theme=val==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):val}
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',applyTheme);
function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.add('hidden'),4000)}
function setSync(text,kind='ok'){$('#sync').textContent=text;$('#sync').dataset.kind=kind}
function notice(text,retry=true){$('#cloud-notice-text').textContent=text;$('#cloud-notice').classList.remove('hidden');$('#sync-retry').classList.toggle('hidden',!retry)}
function remember(){try{localStorage.setItem(KEY,JSON.stringify({uid:activeUID,state:s}))}catch{toast('Device storage is full. Export a backup in Settings.')}}
function mutation(fn,message=''){if(!ready)return;const previous=clone(s),oldXP=game().xp;fn();if(!valid(s)||new Blob([JSON.stringify(s)]).size>780000){s=previous;toast('Unable to save: check the values or export a backup. This library must stay under 780 KB.');return}remember();if(!pending)pendingBase=revision;pending=clone(s);saveDraft();render();setSync('Saving…','saving');const gained=game().xp-oldXP;if(message)toast(message+(gained>0?` · +${gained} XP`:''));flush()}
function saveDraft(){try{localStorage.setItem(DRAFT,JSON.stringify({uid:activeUID,base:pendingBase,state:pending||s}))}catch{}}
function pack(v,r){return {schemaVersion:2,...v,revision:r,updatedAt:serverTimestamp()}}
function remoteValid(d){return d?.schemaVersion===2&&Number.isInteger(d.revision)&&d.revision>=1&&valid(d)}
function applyRemote(data){if(!remoteValid(data))throw Error('invalid-data');s=pure(data);revision=data.revision;remember();applyTheme();render();setSync('Cloud synced');$('#cloud-notice').classList.add('hidden')}
function hasDialog(){return $$('dialog').some(d=>d.open)}
function acceptDeferred(){if(deferred&&!busy&&!pending&&!hasDialog()){let d=deferred;deferred=null;if(d.revision>revision)applyRemote(d)}}
async function flush(){if(!ready||busy||!pending||conflict)return;if(!navigator.onLine){setSync('Offline · saved here','error');notice('Offline. Your edits are stored on this device and will retry when you reconnect.',false);return}busy=true;const candidate=clone(pending),base=pendingBase,e=epoch,target=ref;pending=null;try{await runTransaction(db,async tx=>{const snap=await tx.get(target);if(!snap.exists()||snap.data().revision!==base)throw Error('sync-conflict');tx.set(target,pack(candidate,base+1))});if(e!==epoch)return;revision=base+1;if(pending){pendingBase=revision;saveDraft()}else{try{localStorage.removeItem(DRAFT)}catch{}setSync('Cloud synced');$('#cloud-notice').classList.add('hidden')}}catch(error){if(e!==epoch)return;if(!pending)pending=candidate;pendingBase=base;saveDraft();conflict=error.message==='sync-conflict';setSync('Not synced','error');notice(conflict?'Another device has newer progress. Your edits are safe here. Export a backup in Settings, then choose Retry sync to resolve the conflict.':'Cloud save failed. Your changes are safe on this device. Reconnect and retry.')}finally{if(e===epoch){busy=false;acceptDeferred()}}if(pending&&!conflict&&revision>base)flush()}
function go(r){if(!Object.hasOwn(routes,r))return;route=r;location.hash=r;$('#crumb').textContent=routes[r];render();window.scrollTo({top:0,behavior:'instant'})}
function navHTML(mobile=false){return Object.entries(routes).filter(([k])=>k!=='settings').map(([k,v])=>`<button class="${mobile?'':'nav-item '}${route===k?'active':''}" data-route="${k}" ${route===k?'aria-current="page"':''}>${icon(k)}${v}</button>`).join('')}
function heading(title,sub,action='',eyebrow='Make room for what matters'){return `<div class="page-head"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${action?`<div class="head-actions">${action}</div>`:''}</div>`}
function empty(title,description,action=''){return `<div class="empty">${icon('spark')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`}
const newButton=(type='task',text='Quick add')=>`<button class="primary" data-action="new-${type}">${icon('plus')}${esc(text)}</button>`;
function playerCard(){let g=game();return `<section class="player-card" aria-label="Player progression"><div class="player-top"><div><p class="eyebrow">Your next chapter</p><h2 class="player-title">${esc(g.title)}.<br><span>Keep becoming.</span></h2><p class="player-note">Small wins are how the big things happen.</p></div><div class="level-emblem"><small>LEVEL</small>${g.level}</div></div><div class="xp-line"><span><strong>${g.within}</strong> / ${g.needed} XP</span><span>Level ${g.level+1} at ${g.next} XP</span></div><div class="bar" role="progressbar" aria-label="Progress to next level" aria-valuenow="${g.within}" aria-valuemin="0" aria-valuemax="${g.needed}"><span style="width:${g.within/g.needed*100}%"></span></div><div class="player-bottom"><span>${icon('flame')}<strong>${overallStreak()} day</strong> momentum</span><span>${icon('coin')}<strong>${g.coins}</strong> coins</span><span>${icon('bolt')}<strong>${g.xp}</strong> total XP</span></div></section>`}
function dailyXP(d=today()){let n=s.habitLogs.filter(l=>l.date===d&&l.value>=l.target).reduce((a,l)=>a+l.xp,0)+s.taskLogs.filter(l=>l.done&&l.doneOn===d).reduce((a,l)=>a+l.xp,0);n+=Math.min(s.focusSessions.filter(f=>f.date===d).length,4)*20;return n+questInfo(d).filter(q=>q.done).reduce((a,q)=>a+q.xp,0)}
function dailyCard(){const habits=s.habits.filter(h=>habitDue(h,today())),done=habits.filter(h=>habitDone(h,today())).length,xp=dailyXP();return `<section class="daily-card"><div class="daily-head"><h3>Today’s momentum</h3><span class="pill">${xp>=s.settings.dailyGoal?'Goal reached':'A fresh opportunity'}</span></div><div><div class="daily-score">${xp}<span>/ ${s.settings.dailyGoal} XP</span></div><p class="muted small">${xp>=s.settings.dailyGoal?'You showed up. That’s worth celebrating.':'Build a good day, one small win at a time.'}</p></div><div><div class="bar" style="margin-top:18px"><span style="width:${Math.min(100,xp/s.settings.dailyGoal*100)}%"></span></div><div class="daily-foot"><span>${done}/${habits.length} habits completed</span><span>${s.focusSessions.filter(f=>f.date===today()).reduce((a,f)=>a+f.minutes,0)} min focused</span></div></div></section>`}
function habitRow(h,d,full=false){const l=hlog(h,d),done=habitDone(h,d),value=l?.value||0,target=l?.target||h.target,can=d<=today()&&d>=h.createdOn&&!h.archived;return `<div class="habit-row"><button class="check ${done?'done':''}" data-habit-check="${h.id}" data-date="${d}" aria-pressed="${done}" aria-label="${done?'Undo':'Complete'} ${esc(h.title)}" ${can?'':'disabled'}>${done?icon('check'):''}</button><div class="row-icon ${h.area}">${icon(h.area)}</div><div class="row-content"><button class="row-title ${done?'done-text':''}" data-edit-habit="${h.id}">${esc(h.title)}</button><div class="row-meta"><span>${esc(areas[h.area])}</span><span>·</span><span>${target>1?`${value}/${target} ${esc(h.unit)}`:schedule(h,d).length===7?'Every day':schedule(h,d).map(n=>['Su','Mo','Tu','We','Th','Fr','Sa'][n]).join(', ')}</span>${h.archived?'<span>Archived</span>':''}</div></div>${target>1&&!h.archived?`<div class="stepper"><button data-habit-step="${h.id}" data-date="${d}" data-step="-1" aria-label="Decrease ${esc(h.title)}" ${value===0||!can?'disabled':''}>−</button><button data-habit-step="${h.id}" data-date="${d}" data-step="1" aria-label="Increase ${esc(h.title)}" ${done||!can?'disabled':''}>+</button></div>`:''}${full?`<span class="streak-badge" title="Consecutive scheduled check-ins">${icon('flame')}${habitStreak(h,d)}</span>`:`<span class="xp-tag">${done?'✓ Done':'+'+XP[h.effort]+' XP'}</span>`}</div>`}
function taskRow(t){const log=tlog(t),done=!!log?.done,sub=t.subtasks.length,steps=log?.steps?.length||0;return `<div class="task-row"><button class="check round ${done?'done':''}" data-task-check="${t.id}" aria-pressed="${done}" aria-label="${done?'Undo':'Complete'} ${esc(t.title)}" ${t.archived?'disabled':''}>${done?icon('check'):''}</button><div class="row-content"><button class="row-title ${done?'done-text':''}" data-task-detail="${t.id}">${esc(t.title)}</button><div class="row-meta"><span class="priority-dot ${t.priority}"></span><span>${esc(areas[t.area])}</span>${t.dueDate?`<span>·</span><span ${t.repeat==='none'&&t.dueDate<today()&&!done?'class="danger"':''}>${t.repeat==='none'?(t.dueDate===today()?'Today':dateLabel(t.dueDate)):t.repeat==='daily'?'Daily':'Weekly'}</span>`:''}${sub?`<span>· ${Math.min(steps,sub)}/${sub} steps</span>`:''}${t.status==='doing'&&!done?'<span>· In progress</span>':''}</div></div><span class="xp-tag">${done?'✓ Done':'+'+XP[t.effort]+' XP'}</span></div>`}
function sortedTasks(arr){return [...arr].sort((a,b)=>({high:0,normal:1,low:2}[a.priority]-{high:0,normal:1,low:2}[b.priority])||(a.dueDate||'9999').localeCompare(b.dueDate||'9999'))}
function todayPage(){const d=today(),due=s.habits.filter(h=>habitDue(h,d)),tasks=sortedTasks(s.tasks.filter(t=>taskDue(t)&&!taskDone(t)&&(!t.dueDate||t.dueDate<=d))).slice(0,4),name=s.settings.name||profileName;return heading(`Make today count, ${name}.`,'Not everything. Just the things that matter.',`<span class="date-chip">${icon('calendar')}${dateLabel(d,{weekday:'short',month:'short',day:'numeric'})}</span>${newButton()}`,dateLabel(d,{weekday:'long',month:'long',day:'numeric'}))+`<div class="dashboard-hero">${playerCard()}${dailyCard()}</div><div class="section-grid"><section class="panel"><div class="panel-head"><div><h2>Your daily rituals</h2><p>${due.filter(h=>habitDone(h,d)).length} of ${due.length} complete · make a little room</p></div><button class="link-btn" data-route="habits">View all ${icon('right')}</button></div><div class="panel-body">${due.length?due.slice(0,5).map(h=>habitRow(h,d)).join(''):empty('Space for a small ritual','No habits scheduled for today. Rest, or start something new.',newButton('habit','Add a habit'))}</div><div class="panel-footer"><span>Small actions. Strong foundations.</span><button class="link-btn" data-action="new-habit">${icon('plus')}New habit</button></div></section><section class="panel"><div class="panel-head"><div><h2>Move things forward</h2><p>Your most important next steps</p></div><button class="link-btn" data-route="tasks">All tasks ${icon('right')}</button></div><div class="panel-body">${tasks.length?tasks.map(taskRow).join(''):empty('A little breathing room','Add one thing you’d feel good about finishing today.',newButton('task','Add your first task'))}</div><div class="panel-footer"><span>Need some uninterrupted time?</span><button class="link-btn" data-route="focus">${icon('focus')}Start focus</button></div></section></div><div class="section-title"><div><h2>Daily side quests</h2><p>A little extra motivation. Resets each day.</p></div><span class="pill">${questInfo(d).filter(q=>q.done).length}/3 complete</span></div><div class="quest-strip">${questInfo(d).map(q=>`<div class="quest ${q.done?'completed':''}"><div class="quest-top">${icon(q.done?'check':q.icon)}<span class="xp-tag">${q.done?'Earned':'+'+q.xp+' XP'}</span></div><h3>${q.name}</h3><p>${q.description}</p></div>`).join('')}</div>`}
function habitsPage(){const d=selectedDate||today(),days=Array.from({length:7},(_,i)=>addDays(today(),i-6)),habits=s.habits.filter(h=>showArchived?h.archived:habitDue(h,d));return heading('Build your everyday.','Rituals that fit your life. Progress at your pace.',newButton('habit','New habit'),'Habits / consistency over intensity')+`<div class="week-strip" aria-label="Check-in date">${days.map(k=>`<button class="day ${d===k?'selected':''} ${s.habitLogs.some(l=>l.date===k&&l.value>=l.target)?'has-activity':''}" data-select-date="${k}" aria-pressed="${d===k}" aria-label="${dateLabel(k,{weekday:'long',month:'long',day:'numeric'})}"><span>${dateLabel(k,{weekday:'short'})}</span><strong>${Number(k.slice(-2))}</strong><span class="day-mark"></span></button>`).join('')}</div><div class="toolbar"><h2>${d===today()?'Today’s habits':dateLabel(d,{weekday:'long',month:'short',day:'numeric'})}</h2><div class="segments"><button data-action="active-habits" class="${!showArchived?'active':''}">Scheduled</button><button data-action="archived-habits" class="${showArchived?'active':''}">Archived</button></div></div><section class="panel habit-list">${habits.length?habits.map(h=>habitRow(h,d,true)).join(''):empty(showArchived?'No archived habits':'A little space to begin',showArchived?'Habits you archive will appear here.':'No habits scheduled on this day.',newButton('habit','Create a habit'))}</section><p class="help" style="margin-top:16px">Check in for today or the last 6 days. Streaks count consecutive scheduled days, not rest days. Starter habits are suggestions—edit or archive them anytime.</p>`}
function tasksPage(){let tasks=s.tasks.filter(t=>taskFilter==='archived'?t.archived:!t.archived).filter(t=>taskArea==='all'||t.area===taskArea).filter(t=>(t.title+' '+t.notes).toLowerCase().includes(taskSearch.toLowerCase()));if(taskFilter==='open')tasks=tasks.filter(t=>!taskDone(t));if(taskFilter==='today')tasks=tasks.filter(t=>taskDue(t)&&!taskDone(t)&&(!t.dueDate||t.dueDate<=today()));if(taskFilter==='done')tasks=tasks.filter(t=>taskDone(t));tasks=sortedTasks(tasks);const tabs={all:'All',open:'Open',today:'Today',done:'Done',archived:'Archived'};return heading('Clear head. Next step.','Capture the big things. Break them into small wins.',newButton('task','New task'),'Tasks / one thing at a time')+`<div class="toolbar"><div class="toolbar-left"><input class="search-input" id="task-search" type="search" aria-label="Search tasks" placeholder="Search tasks…" value="${esc(taskSearch)}"><select id="task-area" aria-label="Filter by area"><option value="all">All areas</option>${Object.entries(areas).map(([k,v])=>`<option value="${k}" ${taskArea===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="segments"><button data-task-view="list" class="${taskView==='list'?'active':''}">List</button><button data-task-view="board" class="${taskView==='board'?'active':''}">Board</button></div></div><div class="toolbar"><div class="segments">${Object.entries(tabs).map(([k,v])=>`<button data-task-filter="${k}" class="${taskFilter===k?'active':''}">${v}</button>`).join('')}</div><span class="small muted">${tasks.length} task${tasks.length===1?'':'s'}</span></div>${taskView==='board'?`<div class="board">${[['todo','To do'],['doing','In progress'],['done','Done']].map(([k,v])=>{let a=tasks.filter(t=>k==='done'?taskDone(t):!taskDone(t)&&t.status===k);return `<section class="board-column"><h3>${v}<span class="muted">${a.length}</span></h3>${a.map(taskRow).join('')||'<p class="help">A little room for your next step.</p>'}</section>`}).join('')}</div>`:`<section class="panel task-list">${tasks.length?tasks.map(taskRow).join(''):empty('Nothing here. That’s okay.',taskSearch?'Try another search or change your filters.':'Capture a next step when you’re ready.',newButton('task','New task'))}</section>`}<p class="help" style="margin-top:16px">Recurring tasks have one check-in per scheduled day. Completing a task also completes its checklist. Future recurring tasks can’t be checked in early.</p>`}
function achievements(){const g=game();return [{title:'First little win',desc:'Complete your first habit, task, or focus session.',value:g.hc+g.tc+g.focus,target:1,icon:'spark'},{title:'Ritual builder',desc:'Complete 7 habit check-ins.',value:g.hc,target:7,icon:'habits'},{title:'Getting things done',desc:'Finish 10 tasks or recurring task occurrences.',value:g.tc,target:10,icon:'tasks'},{title:'A week of momentum',desc:'Be active on 7 consecutive days.',value:bestStreak(),target:7,icon:'flame'},{title:'Deep thinker',desc:'Finish 10 focus sessions.',value:g.focus,target:10,icon:'focus'},{title:'Pathfinder',desc:'Reach level 5.',value:g.level,target:5,icon:'journey'}]}
function bestStreak(){let days=[...activeDays()].sort(),best=0,n=0,last='';for(const d of days){n=last&&addDays(last,1)===d?n+1:1;best=Math.max(best,n);last=d}return best}
function activity(){const rows=[];for(const l of s.habitLogs.filter(l=>l.value>=l.target))rows.push({title:s.habits.find(h=>h.id===l.habitId)?.title||'Habit check-in',date:l.date,xp:l.xp,icon:'habits'});for(const l of s.taskLogs.filter(l=>l.done))rows.push({title:s.tasks.find(t=>t.id===l.taskId)?.title||'Task completed',date:l.doneOn,xp:l.xp,icon:'tasks'});const fs={};for(const f of [...s.focusSessions].sort((a,b)=>a.completedAt.localeCompare(b.completedAt))){fs[f.date]=(fs[f.date]||0)+1;rows.push({title:`${f.minutes} minutes of focus${f.taskTitle?' · '+f.taskTitle:''}`,date:f.date,xp:fs[f.date]<=4?20:0,icon:'focus'})}for(const d of activeDays())for(const q of questInfo(d).filter(q=>q.done))rows.push({title:q.name+' · side quest',date:d,xp:q.xp,icon:'star'});return rows.sort((a,b)=>b.date.localeCompare(a.date)).slice(0,15)}
function journeyPage(){let g=game(),a=achievements(),rows=activity();return heading('Look how far you’re going.','Every small action is part of a bigger story.',`<span class="pill">Level ${g.level} · ${g.title}</span>`,'Journey / progress, not perfection')+`<div class="metric-grid">${[[g.xp,'Total experience','Every completed action counts'],[g.coins,'Available coins','1 coin for every 10 XP'],[bestStreak()+(bestStreak()===1?' day':' days'),'Best momentum streak','A day with at least one win'],[g.minutes+' min','Focused time','Real sessions. Real space.']].map(([v,k,n])=>`<section class="metric"><p class="eyebrow">${k}</p><strong>${v}</strong><p>${n}</p></section>`).join('')}</div><div class="section-title"><h2>Milestones worth keeping</h2><span class="small muted">${a.filter(x=>x.value>=x.target).length}/${a.length} unlocked</span></div><div class="achievement-grid">${a.map(x=>`<section class="achievement ${x.value<x.target?'locked':''}"><div class="badge-icon">${icon(x.icon)}</div><h3>${x.title}</h3><p>${x.desc}</p><small>${x.value>=x.target?'✓ Unlocked':Math.min(x.value,x.target)+' / '+x.target}</small></section>`).join('')}</div><div class="section-title"><div><h2>A little reward goes a long way</h2><p>Virtual coins. Real moments you choose.</p></div><button class="link-btn" data-action="new-reward">${icon('plus')}Add reward</button></div><div class="reward-grid">${s.rewards.filter(r=>!r.archived).map(r=>`<section class="reward"><div class="row-icon life">${icon('gift')}</div><div class="row-content"><h3>${esc(r.title)}</h3><p>${r.cost} coins · <button class="link-btn" data-delete-reward="${r.id}" style="min-height:24px;font-size:11px">Remove</button></p></div><button class="${g.coins>=r.cost?'primary':''}" data-redeem="${r.id}" ${g.coins<r.cost?'disabled':''}>${icon('coin')}Claim</button></section>`).join('')||empty('Something to look forward to','Add a reward that feels good to you.')} </div>${g.coins<0?'<p class="help danger" style="margin-top:12px">Some completed actions were undone after spending coins. New earnings first cover this balance.</p>':''}<div class="section-title"><h2>Your recent wins</h2><span class="small muted">Last 15 actions</span></div><section class="panel">${rows.map(r=>`<div class="activity-row"><div class="row-icon">${icon(r.icon)}</div><div class="row-content"><strong>${esc(r.title)}</strong><p>${dateLabel(r.date,{weekday:'short',month:'short',day:'numeric'})}</p></div><span class="xp-tag">+${r.xp} XP</span></div>`).join('')||empty('The first win is waiting','Check in a habit or finish a task. Your story starts there.')}</section>${s.redemptions.length?`<div class="section-title"><h2>Rewards enjoyed</h2></div><section class="panel">${s.redemptions.slice(-5).reverse().map(r=>`<div class="activity-row">${icon('gift')}<div class="row-content"><strong>${esc(r.title)}</strong><p>${dateLabel(r.date)} · ${r.cost} coins</p></div></div>`).join('')}</section>`:''}<p class="help" style="margin-top:20px">Progress is personal, not a competition. Undoing a completion removes its XP and related quest bonuses. Rechecking the same action never stacks duplicate XP. Achievements reflect your current recorded history.</p>`}
function remaining(){if(!timer)return focusMinutes*60000;return timer.endsAt?Math.max(0,timer.endsAt-Date.now()):timer.remainingMs}
function timerText(){let secs=Math.ceil(remaining()/1000);return String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0')}
function focusPage(){let selected=timer?.taskId||'',f=s.focusSessions.filter(x=>x.date===today());return heading('One thing. Your full attention.','Make a little space for the work that matters.','','Focus / less noise, more presence')+`<div class="focus-layout"><section class="timer-card"><p class="eyebrow">Your quiet corner</p><div class="segments">${[25,45,60].map(n=>`<button data-duration="${n}" class="${(timer?.plannedMinutes||focusMinutes)===n?'active':''}" ${timer?'disabled':''}>${n} min</button>`).join('')}</div><div class="timer-ring"><div class="timer-digits" id="timer-digits" role="timer" aria-label="Focus time remaining">${timerText()}</div><p class="muted small" id="timer-status">${timer?.endsAt?'Stay with this moment.':timer?'Paused. Take a breath.':'Ready when you are.'}</p></div><label class="field" style="max-width:320px;margin:auto">Focus on <select id="focus-task" ${timer?'disabled':''}><option value="">Just a little quiet time</option>${s.tasks.filter(t=>!t.archived&&!taskDone(t)).map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.title)}</option>`).join('')}</select></label><div class="timer-actions"><button class="primary" data-action="timer-toggle">${icon(timer?.endsAt?'pause':'play')}${timer?.endsAt?'Pause':timer?'Resume':'Start focus'}</button>${timer?'<button class="icon-btn" data-action="timer-reset" aria-label="End focus without reward">'+icon('reset')+'</button>':''}</div><p class="help">Finish a full session to earn 20 XP.<br>XP applies to the first 4 completed sessions per day.</p></section><div><section class="panel focus-tips"><h2>Give yourself a little room.</h2><ul><li>Choose one small outcome before you start.</li><li>Put distractions out of reach. Silence isn’t required.</li><li>Your timer survives a refresh on this device.</li><li>When time is up, take a break. You’ve earned it.</li></ul><p class="help">The timer uses actual elapsed time and continues while this tab is in the background. Reopen Folio to record a session that ends while the browser is closed.</p></section><div class="section-title"><h2>Today’s focus</h2><span class="pill">${f.reduce((n,v)=>n+v.minutes,0)} min</span></div><section class="panel">${f.length?f.slice(-5).reverse().map(x=>`<div class="activity-row">${icon('focus')}<div class="row-content"><strong>${x.minutes} focused minutes</strong><p>${esc(x.taskTitle||'A little quiet time')}</p></div>${icon('check')}</div>`).join(''):empty('Your time is yours','Start a session and make it count.')}</section></div></div>`}
let focusMinutes=25;
function settingsPage(){return heading('Make it feel like you.','A few preferences. A little peace of mind.','','Settings / your space, your rules')+`<div class="settings-grid"><section class="panel settings-section"><h2>Your space</h2><p>Keep your rhythm personal.</p><form id="settings-form" class="fields"><label class="field">Display name<input name="name" maxlength="40" value="${esc(s.settings.name||profileName)}" required></label><div class="field-row"><label class="field">Daily XP goal<input name="goal" type="number" min="10" max="1000" value="${s.settings.dailyGoal}" required></label><label class="field">Appearance<select name="theme">${['system','light','dark'].map(v=>`<option value="${v}" ${s.settings.theme===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label></div><label class="field">Calendar time zone<input name="zone" value="${esc(s.settings.timeZone)}" placeholder="America/Sao_Paulo" required></label><p class="help">Habit days, streaks, and daily quests use this time zone. Changing it does not rewrite existing check-ins.</p><button class="primary">Save preferences</button></form></section><div class="fields"><section class="panel settings-section"><h2>Safe, synced, yours.</h2><p>Google sign-in. Owner-only Firestore access. No public profiles or leaderboards.</p><p class="help">Library size: ${Math.ceil(new Blob([JSON.stringify(s)]).size/1024)} KB / 780 KB. Private local recovery copies remain on this browser after sign-out; clear site data on shared devices.</p><div class="compact-actions"><button data-action="export">${icon('download')}Export backup</button><button data-action="import">${icon('upload')}Import backup</button></div><p class="help" style="margin-top:14px">Import replaces habit and task progress, including rewards. It never changes your book library.</p></section><section class="panel settings-section"><h2>Your book library is still here.</h2><p>Your original Folio books and reading progress are preserved in a separate cloud document.</p><a href="./books.html">Open book tracker →</a></section><section class="panel settings-section"><h2>A gentle game, not another chore.</h2><p>10 / 20 / 40 XP per action, based on effort. Side quests add a daily bonus. Level thresholds rise as you grow. No XP penalties for missed days.</p><button data-action="signout" class="ghost danger">${icon('logout')}Sign out</button></section></div></div>`}
function render(){if(!s)return;applyTheme();$('.desktop-nav').innerHTML=navHTML();$('.mobile-nav').innerHTML=navHTML(true);$('#crumb').textContent=routes[route];let g=game(),name=s.settings.name||profileName;$('#top-avatar').textContent=name.slice(0,2).toUpperCase();$('#side-player').innerHTML=`<div class="side-level"><div class="avatar">${esc(name.slice(0,2).toUpperCase())}</div><div><strong style="font-size:13px">${esc(name)}</strong><p class="muted" style="font-size:11px">Level ${g.level} · ${g.title}</p></div></div>`;$('#content').innerHTML=({today:todayPage,habits:habitsPage,tasks:tasksPage,focus:focusPage,journey:journeyPage,settings:settingsPage}[route])();}
function openEditor(type,itemId=null){editType=type;editId=itemId;const item=(type==='habit'?s.habits:s.tasks).find(x=>x.id===itemId);$('#editor-title').textContent=(item?'Edit ':'New ')+type;$('#type-tabs').classList.toggle('hidden',!!item);$('#task-fields').classList.toggle('hidden',type!=='task');$('#habit-fields').classList.toggle('hidden',type!=='habit');$$('[data-editor-type]').forEach(b=>b.classList.toggle('active',b.dataset.editorType===type));$('#item-title').value=item?.title||'';$('#item-notes').value=item?.notes||'';$('#item-area').value=item?.area||'life';$('#item-effort').value=item?.effort||'normal';$('#item-due').value=item?.dueDate||today();$('#item-priority').value=item?.priority||'normal';$('#item-repeat').value=item?.repeat||'none';$('#item-status').value=item?.status||'todo';$('#item-subtasks').value=item?.subtasks?.map(x=>x.title).join('\n')||'';$('#item-target').value=item?.target||1;$('#item-unit').value=item?.unit||'check-in';const days=item&&type==='habit'?schedule(item,today()):[0,1,2,3,4,5,6];$('#schedule-picker').innerHTML=['S','M','T','W','T','F','S'].map((d,i)=>`<label><input type="checkbox" name="weekday" value="${i}" ${days.includes(i)?'checked':''} aria-label="${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][i]}"><span>${d}</span></label>`).join('');$('#archive-item').classList.toggle('hidden',!item);$('#archive-item').textContent=item?.archived?'Restore':'Archive';$('#form-error').textContent='';if(!$('#editor').open)$('#editor').showModal();$('#item-title').focus()}
function ensureTaskLog(t){let l=tlog(t);if(!l){l={key:taskKey(t),taskId:t.id,date:today(),done:false,doneOn:'',xp:XP[t.effort],area:t.area,steps:[]};s.taskLogs.push(l)}return l}
function updateHabit(hid,d,value=null){const h=s.habits.find(h=>h.id===hid);if(!h||!habitDue(h,d)||d>today()||d<addDays(today(),-6))return;mutation(()=>{let l=hlog(h,d);if(!l){l={id:h.id+'|'+d,habitId:h.id,date:d,value:0,target:h.target,xp:XP[h.effort],area:h.area};s.habitLogs.push(l)}l.value=value===null?(l.value>=l.target?0:l.target):Math.max(0,Math.min(l.target,value))},'Check-in updated')}
function toggleTask(tid){const t=s.tasks.find(t=>t.id===tid);if(!t||t.archived)return;if(t.repeat!=='none'&&!taskDue(t)){toast('This recurring task is not scheduled for today.');return}mutation(()=>{const l=ensureTaskLog(t);l.done=!l.done;l.doneOn=l.done?today():'';if(l.done)l.steps=t.subtasks.map(x=>x.id)},'Task updated');if($('#detail').open)openDetail(tid)}
function openDetail(tid){detailId=tid;const t=s.tasks.find(t=>t.id===tid);if(!t)return;$('#detail-title').textContent=t.title;const l=tlog(t),done=!!l?.done;$('#detail-body').innerHTML=`<div class="row-meta"><span class="pill">${esc(areas[t.area])}</span><span>${XP[t.effort]} XP</span><span>· ${esc(t.priority)} priority</span>${t.repeat!=='none'?'<span>· '+t.repeat+'</span>':''}</div>${t.notes?`<div class="note-box">${esc(t.notes)}</div>`:''}${t.subtasks.length?`<div class="subtasks">${t.subtasks.map(q=>`<label class="subtask"><input type="checkbox" data-subtask="${q.id}" data-task="${t.id}" ${l?.steps.includes(q.id)?'checked':''} ${t.archived?'disabled':''}><span>${esc(q.title)}</span></label>`).join('')}</div>`:'<p class="help" style="margin:20px 0">One clear next step is enough.</p>'}<div class="form-actions"><button data-edit-task="${t.id}">${icon('edit')}Edit</button><button class="primary" data-task-check="${t.id}" ${t.archived?'disabled':''}>${icon('check')}${done?'Undo completion':'Complete task'}</button></div>`;if(!$('#detail').open)$('#detail').showModal()}
$('#edit-form').onsubmit=e=>{e.preventDefault();const title=$('#item-title').value.trim(),notes=$('#item-notes').value.trim(),area=$('#item-area').value,effort=$('#item-effort').value,d=today();if(!title){$('#form-error').textContent='Give this a short, clear name.';return}if(editType==='habit'){const days=$$('#schedule-picker input:checked').map(i=>Number(i.value)),target=Number($('#item-target').value),unit=$('#item-unit').value.trim();if(!days.length||!Number.isInteger(target)||target<1||target>1000||!unit){$('#form-error').textContent='Choose at least one day, a target from 1–1000, and a unit.';return}mutation(()=>{let h=s.habits.find(h=>h.id===editId);if(h){Object.assign(h,{title,notes,area,effort,target,unit});if(schedule(h,d).join(',')!==days.join(',')){h.scheduleChanges=h.scheduleChanges.filter(c=>c.from!==d);h.scheduleChanges.push({from:d,days})}}else s.habits.push({id:id(),title,notes,area,effort,target,unit,createdOn:d,scheduleChanges:[{from:d,days}],archived:false})},'Habit saved')}else{const repeat=$('#item-repeat').value,dueDate=$('#item-due').value,priority=$('#item-priority').value,status=$('#item-status').value,lines=$('#item-subtasks').value.split('\n').map(x=>x.trim()).filter(Boolean);if(lines.length>8||lines.some(x=>x.length>100)||repeat!=='none'&&!dueDate){$('#form-error').textContent='Use up to 8 checklist steps, each under 100 characters. Recurring tasks need a start date.';return}const previous=s.tasks.find(t=>t.id===editId);if(previous&&previous.repeat!==repeat&&s.taskLogs.some(l=>l.taskId===previous.id)){ $('#form-error').textContent='This task already has history. Archive it and create a new task to change its repeat schedule.';return}if(!editId&&route==='tasks'){taskFilter='open';taskSearch='';taskArea='all'}mutation(()=>{let t=s.tasks.find(t=>t.id===editId);const subtasks=lines.map(title=>({id:t?.subtasks.find(q=>q.title===title)?.id||id(),title}));if(t){Object.assign(t,{title,notes,area,effort,dueDate,priority,repeat,status,subtasks});for(const l of s.taskLogs.filter(l=>l.taskId===t.id)){l.steps=l.steps.filter(x=>subtasks.some(q=>q.id===x));if(l.done)l.steps=subtasks.map(q=>q.id)}}else s.tasks.push({id:id(),title,notes,area,effort,dueDate,priority,repeat,status,subtasks,createdOn:d,archived:false})},'Task saved')}$('#editor').close()};
$('#archive-item').onclick=()=>{const list=editType==='habit'?s.habits:s.tasks,item=list.find(x=>x.id===editId);if(!item)return;mutation(()=>item.archived=!item.archived,item.archived?'Restored':'Archived · your history is preserved');$('#editor').close()};
function exportBackup(){const blob=new Blob([JSON.stringify({format:'folio-quest',version:2,exportedAt:new Date().toISOString(),state:s},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='folio-progress-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error();const v=JSON.parse(await f.text());if(v.format!=='folio-quest'||v.version!==2||!valid(v.state))throw Error();if(confirm('Replace your habit and task progress, including XP and rewards, with this backup? Your book library will not change.'))mutation(()=>s=pure(v.state),'Backup restored')}catch{toast('Invalid backup. Choose a Folio habit/task JSON export under 1 MB.')}e.target.value=''};
function storeTimer(){try{if(timer)localStorage.setItem(TIMER,JSON.stringify(timer));else localStorage.removeItem(TIMER)}catch{}}
function startPause(){if(timer?.endsAt){const now=Date.now();timer.activeMs+=Math.min(timer.remainingMs,Math.max(0,now-timer.runStarted));timer.remainingMs=Math.max(0,timer.endsAt-now);timer.endsAt=null;timer.runStarted=null}else if(timer){timer.runStarted=Date.now();timer.endsAt=Date.now()+timer.remainingMs}else{const t=s.tasks.find(t=>t.id===$('#focus-task')?.value);timer={id:id(),uid:activeUID,plannedMinutes:focusMinutes,remainingMs:focusMinutes*60000,endsAt:Date.now()+focusMinutes*60000,runStarted:Date.now(),activeMs:0,taskId:t?.id||'',taskTitle:t?.title||''}}storeTimer();render()}
function tick(){if(timer?.uid!==activeUID)return;if(timer?.endsAt&&Date.now()>=timer.endsAt&&ready){const completed=timer;completed.activeMs+=completed.remainingMs;if(completed.activeMs+1000>=completed.plannedMinutes*60000&&!s.focusSessions.some(f=>f.id===completed.id)){mutation(()=>s.focusSessions.push({id:completed.id,date:today(),minutes:completed.plannedMinutes,taskTitle:completed.taskTitle,completedAt:new Date().toISOString()}),'Focus complete. Take a breath.')}timer=null;storeTimer();if(route==='focus')render()}if($('#timer-digits'))$('#timer-digits').textContent=timer?timerText():String(focusMinutes).padStart(2,'0')+':00'}setInterval(tick,1000);
function quickSearch(){const q=$('#global-search').value.trim().toLowerCase(),matches=[...s.tasks.filter(t=>!t.archived).map(t=>({...t,type:'task'})),...s.habits.filter(h=>!h.archived).map(h=>({...h,type:'habit'}))].filter(x=>x.title.toLowerCase().includes(q)).slice(0,8);$('#quick-results').innerHTML=matches.map(x=>`<button data-quick-item="${x.id}" data-type="${x.type}">${icon(x.type==='habit'?'habits':'tasks')}<span>${esc(x.title)}<small>${x.type==='habit'?'Habit':'Task'} · ${areas[x.area]}</small></span></button>`).join('')||'<p class="help">No matches. Capture a new task or habit above.</p>'}$('#global-search').oninput=quickSearch;
function openCommand(){$('#global-search').value='';quickSearch();$('#command-dialog').showModal();$('#global-search').focus()}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.close){$('#'+d.close).close();return}if(!ready)return;if(d.route){go(d.route);return}if(d.editorType){openEditor(d.editorType);return}if(d.editHabit){openEditor('habit',d.editHabit);return}if(d.editTask){$('#detail').close();openEditor('task',d.editTask);return}if(d.habitCheck){updateHabit(d.habitCheck,d.date);return}if(d.habitStep){const h=s.habits.find(h=>h.id===d.habitStep);updateHabit(d.habitStep,d.date,(hlog(h,d.date)?.value||0)+Number(d.step));return}if(d.taskCheck){toggleTask(d.taskCheck);return}if(d.taskDetail){openDetail(d.taskDetail);return}if(d.selectDate){selectedDate=d.selectDate;render();return}if(d.taskFilter){taskFilter=d.taskFilter;render();return}if(d.taskView){taskView=d.taskView;if(taskView==='board'&&taskFilter==='open')taskFilter='all';render();return}if(d.duration){focusMinutes=Number(d.duration);render();return}if(d.quickItem){$('#command-dialog').close();d.type==='habit'?openEditor('habit',d.quickItem):openDetail(d.quickItem);return}if(d.redeem){const r=s.rewards.find(r=>r.id===d.redeem);if(!r||game().coins<r.cost)return;if(confirm(`Spend ${r.cost} virtual coins on “${r.title}”?`))mutation(()=>s.redemptions.push({id:id(),title:r.title,cost:r.cost,date:today()}),'Reward claimed. Enjoy your moment.');return}if(d.deleteReward){if(confirm('Remove this reward? Past claims will stay in your history.'))mutation(()=>s.rewards.find(r=>r.id===d.deleteReward).archived=true,'Reward removed');return}switch(d.action){case'new-task':openEditor('task');break;case'new-habit':openEditor('habit');break;case'command':openCommand();break;case'quick-task':$('#command-dialog').close();openEditor('task');break;case'quick-habit':$('#command-dialog').close();openEditor('habit');break;case'active-habits':showArchived=false;render();break;case'archived-habits':showArchived=true;render();break;case'new-reward':$('#reward-form').reset();$('#reward-dialog').showModal();break;case'export':exportBackup();break;case'import':$('#import-file').click();break;case'timer-toggle':startPause();break;case'timer-reset':if(confirm('End this session? Unfinished sessions earn no XP.')){timer=null;storeTimer();render()}break;case'signout':if((pending||busy)&&!confirm('Some changes are not synced. Export a backup first. Sign out anyway?'))return;for(const dialog of $$('dialog[open]'))dialog.close();await signOut(auth);break}});
document.addEventListener('input',e=>{if(e.target.id==='task-search'){const pos=e.target.selectionStart;taskSearch=e.target.value;render();$('#task-search')?.focus();$('#task-search')?.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.id==='task-area'){taskArea=e.target.value;render()}if(e.target.dataset.subtask){const t=s.tasks.find(t=>t.id===e.target.dataset.task);if(!t||t.archived)return;if(t.repeat!=='none'&&!taskDue(t)){toast('This task is not scheduled today.');openDetail(t.id);return}mutation(()=>{const l=ensureTaskLog(t);if(e.target.checked)l.steps=[...new Set([...l.steps,e.target.dataset.subtask])];else l.steps=l.steps.filter(x=>x!==e.target.dataset.subtask);l.done=t.subtasks.length>0&&t.subtasks.every(x=>l.steps.includes(x.id));l.doneOn=l.done?today():''},'Checklist updated');openDetail(t.id)}});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();const form=new FormData(e.target),zone=form.get('zone').trim();try{new Intl.DateTimeFormat('en',{timeZone:zone}).format()}catch{toast('Use a valid time zone, such as America/Sao_Paulo.');return}mutation(()=>{s.settings={name:form.get('name').trim(),dailyGoal:Number(form.get('goal')),theme:form.get('theme'),timeZone:zone}},'Preferences saved')}});
$('#reward-form').onsubmit=e=>{e.preventDefault();const title=$('#reward-name').value.trim(),cost=Number($('#reward-cost').value);if(!title)return;mutation(()=>s.rewards.push({id:id(),title,cost,archived:false}),'A little motivation added');$('#reward-dialog').close()};
for(const d of $$('dialog'))d.addEventListener('close',acceptDeferred);
document.addEventListener('keydown',e=>{if(!ready)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}else if(e.key.toLowerCase()==='n'&&!e.metaKey&&!e.ctrlKey&&!hasDialog()&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();openEditor('task')}});
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(Object.hasOwn(routes,r)&&route!==r){route=r;render()}});
$('#sync-retry').onclick=async()=>{if(!ready){if(auth.currentUser)handleUser(auth.currentUser);return}if(conflict){if(!confirm('Another device has newer cloud progress. Replace it with this device’s current progress? Cancel keeps both copies unchanged. Export a backup first if unsure.'))return;try{const latest=await getDocFromServer(ref);localStorage.setItem('folio-quest-before-conflict-v2',JSON.stringify(latest.data()));revision=latest.data().revision;pendingBase=revision;conflict=false;saveDraft()}catch{toast('Unable to read cloud data. Please try again.');return}}flush()};
$('#signin').onclick=async()=>{try{$('#signin').disabled=true;await setPersistence(auth,browserLocalPersistence);await signInWithPopup(auth,provider)}catch(error){$('#signin').disabled=false;$('#signin').textContent='Continue with Google';$('#auth-message').textContent=error.code==='auth/popup-blocked'?'Allow pop-ups for this site, then try again.':error.code==='auth/popup-closed-by-user'?'Sign-in was cancelled. Your space will be here.':'Unable to finish sign-in. Please try again.'}};
async function handleUser(user){const e=++epoch;if(unsub){unsub();unsub=null}ready=false;busy=false;pending=null;deferred=null;conflict=false;ref=null;$('#app').hidden=true;$('#auth-screen').hidden=false;$('#cloud-notice').classList.add('hidden');activeUID=user?.uid||null;
 if(!user){s=null;$('#signin').disabled=false;$('#signin').textContent='Continue with Google';$('#auth-message').textContent='Your approved Google account is the only account with access.';applyTheme();return}
 profileName=(user.displayName||'You').split(' ')[0];$('#signin').disabled=true;$('#signin').textContent='Opening your space…';$('#auth-message').textContent='Checking your private cloud access…';
 try{ref=doc(db,'users',user.uid,'tracker','state');const target=ref;const snap=await getDocFromServer(target);if(e!==epoch)return;if(!snap.exists()){let initial=seed();try{let cached=JSON.parse(localStorage.getItem(KEY)||'null');if(cached?.uid===user.uid&&valid(cached.state))initial=pure(cached.state)}catch{}await runTransaction(db,async tx=>{const check=await tx.get(target);if(!check.exists())tx.set(target,pack(initial,1))})}const latest=await getDocFromServer(target);if(e!==epoch)return;applyRemote(latest.data());ready=true;let draft=null;try{draft=JSON.parse(localStorage.getItem(DRAFT)||'null')}catch{}if(draft?.uid===user.uid&&valid(draft.state)&&Number.isInteger(draft.base)){s=pure(draft.state);pending=clone(s);pendingBase=draft.base;conflict=pendingBase!==revision;remember();render();if(conflict){setSync('Not synced','error');notice('Recovered unsynced changes from this device. The cloud library is newer. Export a backup, then choose Retry sync to resolve.')}else flush()}$('#auth-screen').hidden=true;$('#app').hidden=false;unsub=onSnapshot(target,{includeMetadataChanges:true},snap=>{if(e!==epoch||!snap.exists()||snap.metadata.hasPendingWrites||snap.metadata.fromCache)return;try{const data=snap.data();if(!remoteValid(data))throw Error();if(data.revision<=revision)return;if(busy||pending||hasDialog())deferred=data;else applyRemote(data)}catch{setSync('Sync needs attention','error');notice('Cloud data could not be loaded. Your device copy is preserved. Export a backup in Settings.',false)}},()=>{setSync('Connection interrupted','error');notice('Live updates are unavailable. Reconnect or sign in again; local edits remain saved.')});if(timer&&timer.uid!==activeUID){timer=null;storeTimer()}tick()}
 catch(error){if(e!==epoch)return;$('#signin').disabled=false;$('#signin').textContent='Try Google sign-in again';$('#auth-message').textContent=error.code==='permission-denied'?'This Google account is not authorized. Use the project owner’s approved account.':'Unable to open your cloud workspace. Check your internet connection and try again. Existing books and progress have not been removed.'}}
onAuthStateChanged(auth,handleUser);
window.addEventListener('online',()=>{if(ready)flush()});window.addEventListener('offline',()=>{if(ready){setSync('Offline · saved here','error');notice('Offline. New changes will be saved on this device until you reconnect.',false)}});
window.addEventListener('beforeunload',e=>{if(pending||busy){e.preventDefault();e.returnValue=''}});
setInterval(()=>{if(ready&&today()!==render.lastDay){render.lastDay=today();selectedDate=today();render()}},30000);
